/**
 * 發布安全：未確定（uncertain）題目不得以任何路徑發布給學生（Sprint 7.9）。
 *
 * 背景：Sprint 7.8 的閘門只有 blocking／warning 兩種結果，warning 完全不影響發布。
 * 對抗式試點證實這是一個發行安全缺口——答案只是教材語句**改寫**（沒有逐字依據）的題目
 * 會收到警告但仍然自動發布。本檔把「未確定 → 暫緩自動發布」寫成可執行契約：
 *
 *   1. 三條發布路徑（changeQuestionStatus／recordAutoValidationAndPublish／
 *      publishAutoGeneratedQuestion）都必須查核 teacher_confirmation_required。
 *   2. 即使資料庫中仍是 published（舊資料或人為操作），題目也不會進入學生練習。
 *   3. 教師確認（人工覆核或重新驗證通過）是唯一的解除途徑。
 *   4. 正常的題目仍然可以自動發布，未確定的題目不影響其他題目（保留自學可用性）。
 */
import { beforeAll, describe, expect, it } from "vitest";

import { freshTestDatabasePath } from "./test-database";
import { openDocumentForStudents } from "./material-distribution";
import { importTestPilotMaterial } from "./fixtures/pilot-material";

const testDbPath = freshTestDatabasePath("publication-safety");
process.env.APP_DATABASE_PATH = testDbPath;
process.env.LLM_PROVIDER = "mock";
delete process.env.K_SERVICE;

type QuestionService = typeof import("@/server/services/question-service");
type QuestionRepo = typeof import("@/server/repositories/questions");
type PracticeService = typeof import("@/server/services/practice-service");
type PracticeRepo = typeof import("@/server/repositories/practice");
type MaterialsRepo = typeof import("@/server/repositories/materials");
type Seed = typeof import("@/server/seed");
type ReportService = typeof import("@/server/services/question-report-service");
type SessionModule = typeof import("@/server/auth/session");
type TeacherReportsRoute = typeof import("@/app/api/teacher/reports/route");

let questionService: QuestionService;
let questionRepo: QuestionRepo;
let practice: PracticeService;
let practiceRepo: PracticeRepo;
let materialsRepo: MaterialsRepo;
let seed: Seed;
let reports: ReportService;
let session: SessionModule;
let teacherReportsRoute: TeacherReportsRoute;

const TOPIC = "topic-5";
const SECTION = "topic-5-industrial";
const LEARNER = "publish-safety-learner";

interface InsertedQuestion {
  id: string;
  status: string;
  teacherConfirmationRequired: boolean;
}

function insertQuestion(options: {
  id: string;
  excerpt: string;
  blockId: string;
  teacherConfirmationRequired: boolean;
  status?: "draft" | "published";
  /** 以教材語句的改寫作為答案（重疊率高但並非逐字）→ 閘門應判為未確定 */
  paraphrase?: boolean;
}): InsertedQuestion {
  const answer = options.paraphrase ? `課本指出${options.excerpt}` : options.excerpt;
  const created = questionRepo.insertQuestion({
    id: options.id,
    topicId: TOPIC,
    sectionId: SECTION,
    questionType: "mc",
    difficulty: "basic",
    question: "課本如何說明工業發展與城市人口增加的關係？",
    // 標準答案刻意採用教材原句（逐字見於所引段落），令這一題的品質檢查完全通過；
    // 未確定（uncertain）的行為由 teacherConfirmationRequired 標記驅動，不由內容偽造。
    options: [answer, "農業全面機械化", "政府強制遷移人口", "海外移民湧入"],
    correctAnswer: answer,
    acceptedAnswers: [],
    explanation: `課本記載：${answer}。`,
    knowledgePoint: "工業發展與城市化",
    sourceExcerpt: options.excerpt,
    sourceLocation: "合成測試用位置",
    sourceBlockIds: [options.blockId],
    gradingPoints: [],
    origin: "material-ai",
    status: options.status ?? "draft",
    sourceVerified: true,
    qualityWarnings: [],
    skill: null,
    revision: 1,
    autoValidatedAt: null,
    autoValidatedRevision: null,
    autoValidatedFingerprint: null,
    teacherConfirmationRequired: options.teacherConfirmationRequired,
    createdAt: "2026-10-16T00:00:00.000Z",
  });
  return {
    id: created.id,
    status: created.status,
    teacherConfirmationRequired: created.teacherConfirmationRequired,
  };
}

beforeAll(async () => {
  questionService = await import("@/server/services/question-service");
  questionRepo = await import("@/server/repositories/questions");
  practice = await import("@/server/services/practice-service");
  practiceRepo = await import("@/server/repositories/practice");
  materialsRepo = await import("@/server/repositories/materials");
  seed = await import("@/server/seed");
  reports = await import("@/server/services/question-report-service");
  session = await import("@/server/auth/session");
  teacherReportsRoute = await import("@/app/api/teacher/reports/route");

  seed.ensureBootstrap();
  await importTestPilotMaterial();
  for (const block of materialsRepo.listGroundingBlocksForSections(TOPIC, [])) {
    openDocumentForStudents(materialsRepo, block.documentId);
  }
});

function firstSectionBlock() {
  const blocks = materialsRepo.listGroundingBlocksForSections(TOPIC, [SECTION]);
  if (blocks.length === 0) throw new Error("課題5沒有可用教材段落");
  // 標題段落不是可作答的教材內容（它只標示分節），因此取第一個非標題段落
  const block = blocks.find((candidate) => candidate.type !== "heading") ?? blocks[0];
  const sentence = block.text.split(/[。！？\n]/).find((part) => part.trim().length >= 8);
  return { blockId: block.id, excerpt: (sentence ?? block.text).trim().slice(0, 40) };
}

const TEACHER = {
  email: "teacher@example.com",
  name: "歷史科教師",
  role: "teacher" as const,
  learnerId: "teacher:teacher@example.com",
  pictureUrl: null,
};

/** 以教師身分呼叫回報補救 API（與 tests/report-revision.test.ts 相同的方式） */
function patchReport(reportId: string, body: Record<string, unknown>): Promise<Response> {
  const cookie = `hk-history-session=${encodeURIComponent(session.encodeSession(TEACHER))}`;
  return teacherReportsRoute.PATCH(
    new Request(`http://localhost:3000/api/teacher/reports?reportId=${reportId}`, {
      method: "PATCH",
      headers: { cookie, "content-type": "application/json" },
      body: JSON.stringify(body),
    }),
  );
}
describe("未確定題目的自動發布暫緩（三條發布路徑）", () => {
  it("changeQuestionStatus 會拒絕發布", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-status",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });
    expect(() => questionService.changeQuestionStatus(held.id, "published")).toThrowError(/未確定/);
    expect(questionRepo.getQuestion(held.id)?.status).toBe("draft");
  });

  it("recordAutoValidationAndPublish 不會把題目發布", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-auto",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });
    const result = questionService.recordAutoValidationAndPublish(held.id);
    expect(result.status).not.toBe("published");
    expect(questionRepo.getQuestion(held.id)?.status).toBe("draft");
  });

  it("publishAutoGeneratedQuestion 會拒絕自動發布", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-auto-publish",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });
    expect(() => questionService.publishAutoGeneratedQuestion(held.id)).toThrowError(/未確定|教師/);
    expect(questionRepo.getQuestion(held.id)?.status).toBe("draft");
  });

  it("即使資料庫中仍是 published，學生練習也不會取得該題", async () => {
    const { blockId, excerpt } = firstSectionBlock();
    // 這代表舊資料或人為直接改動資料庫的情況：狀態是 published 但標記仍在
    const legacy = insertQuestion({
      id: "q-held-legacy-published",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
      status: "published",
    });
    expect(questionRepo.getQuestion(legacy.id)?.status).toBe("published");
    expect(questionService.isStudentPracticeEligible(questionRepo.getQuestion(legacy.id)!)).toBe(false);

    const assembled = await practice.createPractice({
      learnerId: LEARNER,
      topicId: TOPIC,
      sectionIds: [SECTION],
      questionTypes: ["mc"],
      difficulty: "basic",
      questionCount: 3,
      mode: "standard",
      questionSource: "bank",
      sourceSessionId: null,
    });
    const delivered = practiceRepo.getSessionQuestions(assembled.session.id).map((item) => item.id);
    expect(delivered).not.toContain(legacy.id);
  });

  it("正常的題目仍然可以自動發布（未確定題目不影響其他題目）", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const clean = insertQuestion({
      id: "q-clean",
      blockId,
      excerpt,
      teacherConfirmationRequired: false,
    });
    const published = questionService.recordAutoValidationAndPublish(clean.id);
    expect(published.status).toBe("published");
    expect(questionService.isStudentPracticeEligible(published)).toBe(true);
  });
});

describe("教師確認是唯一的解除途徑", () => {
  it("重新驗證即使通過也不會清除暫緩標記（需教師覆核）", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-revalidate",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });
    // 題目本身的內容完全符合教材（逐字節錄），機器檢查會通過……
    const revalidated = questionService.revalidateQuestion(held.id);
    expect(revalidated.decision).toBe("awaiting-teacher-confirmation");
    expect(revalidated.autoValidated).toBe(false);
    // ……但暫緩標記**不會**由機器動作清除（Sprint 8.6：只有人的決定可以解除）
    expect(questionRepo.getQuestion(held.id)?.teacherConfirmationRequired).toBe(true);

    // 因此仍不可經自動驗證路徑發布
    const auto = questionService.recordAutoValidationAndPublish(held.id);
    expect(auto.status).toBe("draft");
    expect(auto.teacherConfirmationRequired).toBe(true);
    expect(questionRepo.getQuestion(held.id)?.status).toBe("draft");

    // 教師明確覆核後才可發布
    const reviewed = questionService.recordQuestionReview({
      questionId: held.id,
      decision: "approved",
      expectedRevision: questionRepo.getQuestion(held.id)!.revision,
      actor: { email: "teacher@example.com", role: "teacher" },
    });
    expect(reviewed.view.question.status).toBe("published");
    expect(questionRepo.getQuestion(held.id)?.teacherConfirmationRequired).toBe(false);
  });

  it("人工覆核通過會清除暫存標記並發布", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-review",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });
    const result = questionService.recordQuestionReview({
      questionId: held.id,
      decision: "approved",
      expectedRevision: questionRepo.getQuestion(held.id)!.revision,
      actor: { email: "teacher@example.com", role: "teacher" },
    });
    expect(result.view.question.status).toBe("published");
    expect(questionRepo.getQuestion(held.id)?.teacherConfirmationRequired).toBe(false);
  });

  it("教師端的重新驗證路線（回報補救 API）不會自行發布題目", async () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-report-route",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
      status: "published",
    });
    const report = reports.submitQuestionReport(LEARNER, {
      questionId: held.id,
      sessionId: null,
      reason: "other",
      detail: "合成測試：未確定題目的處理",
    });

    const response = await patchReport(report.reportId, { action: "revalidate-question" });
    expect(response.status).toBe(200);
    const payload = (await response.json()) as {
      remediation?: { action?: string; autoValidated?: boolean };
    };
    // Sprint 8.6：內容本身逐字引自教材，機器檢查會通過，但暫緩標記只可由教師覆核解除——
    // 回報補救路線會如實回報「仍待教師確認」，既不當成失敗，也不會自行發布。
    expect(payload.remediation?.action).toBe("awaiting-teacher-confirmation");
    expect(payload.remediation?.autoValidated).toBe(false);
    expect(questionRepo.getQuestion(held.id)?.teacherConfirmationRequired).toBe(true);
    expect(questionRepo.getQuestion(held.id)?.status).toBe("published");
  });

  it("答案只是教材語句的改寫時，重新驗證不會失敗，但仍保持待教師確認", async () => {
    const { blockId, excerpt } = firstSectionBlock();
    // 2026-10-20 放寬「答案只是教材語句的改寫」這項阻礙：這類答案在真實模型很常見，
    // 以往會被判為失敗（revalidate-failed）。現在機器檢查可以通過，但暫緩標記仍只由
    // 教師的人工覆核解除，因此題目不會自行發布。
    const held = insertQuestion({
      id: "q-held-paraphrase-route",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
      paraphrase: true,
    });
    const report = reports.submitQuestionReport(LEARNER, {
      questionId: held.id,
      sessionId: null,
      reason: "answer-disputed",
      detail: "合成測試：答案只是教材語句的改寫",
    });

    const response = await patchReport(report.reportId, { action: "revalidate-question" });
    expect(response.status).toBe(200);
    const payload = (await response.json()) as {
      remediation?: { action?: string; autoValidated?: boolean };
    };
    expect(payload.remediation?.action).toBe("awaiting-teacher-confirmation");
    expect(payload.remediation?.autoValidated).toBe(false);
    expect(questionRepo.getQuestion(held.id)?.teacherConfirmationRequired).toBe(true);
    expect(questionRepo.getQuestion(held.id)?.status).toBe("draft");
    expect(questionService.isStudentPracticeEligible(questionRepo.getQuestion(held.id)!)).toBe(false);
  });

  it("節錄已不在教材段落之中時，重新驗證會失敗並保持暫緩，題目亦不會進入學生練習", async () => {
    const { blockId } = firstSectionBlock();
    // 教材重新匯入後，題目引用的節錄可能已失效；機器檢查必須如實失敗（blocked），
    // 不可因為其他檢查寬鬆而當成通過。
    //
    // 註：單純「答案只是教材語句的改寫」已按擁有者指示放寬，不再判為失敗，只會維持
    // 「待教師確認」（上一條測試已覆蓋該分支）；這裡測試的是節錄失效這條硬性失敗路徑。
    const staleExcerpt = "這段節錄已不在現行教材之中（合成測試）";
    const held = insertQuestion({
      id: "q-held-stale-excerpt",
      blockId,
      excerpt: staleExcerpt,
      teacherConfirmationRequired: true,
    });
    const report = reports.submitQuestionReport(LEARNER, {
      questionId: held.id,
      sessionId: null,
      reason: "answer-disputed",
      detail: "合成測試：節錄已失效",
    });

    const response = await patchReport(report.reportId, { action: "revalidate-question" });
    expect(response.status).toBe(200);
    const payload = (await response.json()) as {
      remediation?: { action?: string; autoValidated?: boolean; issues?: string[] };
    };
    expect(payload.remediation?.action).toBe("revalidate-failed");
    expect(payload.remediation?.autoValidated).toBe(false);
    expect(payload.remediation?.issues?.join("") ?? "").toContain("節錄文字已不在所引用的教材段落之中");
    expect(questionRepo.getQuestion(held.id)?.teacherConfirmationRequired).toBe(true);
    expect(questionRepo.getQuestion(held.id)?.status).toBe("draft");
    expect(questionService.isStudentPracticeEligible(questionRepo.getQuestion(held.id)!)).toBe(false);
  });

  it("下架（停用）仍然有效，且未確定題目不受影響", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const clean = insertQuestion({
      id: "q-clean-withdraw",
      blockId,
      excerpt,
      teacherConfirmationRequired: false,
    });
    const published = questionService.recordAutoValidationAndPublish(clean.id);
    expect(published.status).toBe("published");
    const withdrawn = questionService.changeQuestionStatus(clean.id, "disabled");
    expect(withdrawn.question.status).toBe("disabled");
    expect(questionService.isStudentPracticeEligible(questionRepo.getQuestion(clean.id)!)).toBe(false);
  });

  it("題目內容被修改不會靜默清除暫緩標記", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const held = insertQuestion({
      id: "q-held-edit",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });
    const current = questionRepo.getQuestion(held.id)!;
    questionRepo.updateQuestion(held.id, { ...current, explanation: "教師修訂後的解釋。" });
    const updated = questionRepo.getQuestion(held.id)!;
    // 版本已遞增（舊驗證失效），暫緩標記仍然保留，需重新驗證
    expect(updated.revision).toBeGreaterThan(current.revision);
    expect(updated.teacherConfirmationRequired).toBe(true);
    expect(questionService.isStudentPracticeEligible(updated)).toBe(false);
  });
});

/**
 * 擁有者授權的批次發布（`npm run publish:drafts`）也會把題目送到學生面前，
 * 因此同樣不可帶走「等待教師確認」的題目：這是 Sprint 8.0 審計確認的第三條路徑
 * （腳本刻意繞過逐題覆核，但不能代替教師確認品質閘門無法確認的答案依據）。
 */
describe("擁有者授權的批次發布不會帶走未確定的題目", () => {
  it("候選清單排除等待教師確認的草稿，並把被抽起的題目如實列出", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const normal = insertQuestion({
      id: "q-owner-batch-normal",
      blockId,
      excerpt,
      teacherConfirmationRequired: false,
    });
    const held = insertQuestion({
      id: "q-owner-batch-held",
      blockId,
      excerpt,
      teacherConfirmationRequired: true,
    });

    const { publishable, held: heldList } = questionService.listOwnerPublicationCandidates();
    const publishableIds = publishable.map((question) => question.id);
    const heldIds = heldList.map((question) => question.id);

    expect(publishableIds).toContain(normal.id);
    expect(publishableIds).not.toContain(held.id);
    expect(heldIds).toContain(held.id);
    // 兩份清單互斥且涵蓋全部草稿，令「被抽起」不會是靜默遺漏
    expect(heldIds.filter((id) => publishableIds.includes(id))).toEqual([]);
  });

  it("來源篩選仍然適用（只發布指定來源的草稿）", () => {
    const { blockId, excerpt } = firstSectionBlock();
    const manual = insertQuestion({
      id: "q-owner-batch-manual",
      blockId,
      excerpt,
      teacherConfirmationRequired: false,
    });
    // insertQuestion 的來源固定為 material-ai，因此以 school-paper 篩選時不會出現
    const { publishable } = questionService.listOwnerPublicationCandidates({
      origins: ["school-paper"],
    });
    expect(publishable.map((question) => question.id)).not.toContain(manual.id);
  });
});
